(()=>{'use strict';let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('pgg-saved')||'[]'))}catch{}const cards=[...document.querySelectorAll('.product')];const filters=[...document.querySelectorAll('[data-filter]')];const count=document.querySelector('#result-count');const empty=document.querySelector('#empty');const status=document.querySelector('#save-status');function filter(){const vals=Object.fromEntries(filters.map(x=>[x.dataset.filter,x.value]));let n=0;cards.forEach(c=>{let ok=(!vals.recipient||c.dataset.recipient.split(' ').includes(vals.recipient))&&(!vals.budget||(Number(c.dataset.price)>0&&Number(c.dataset.price)<=Number(vals.budget)))&&(!vals.type||(vals.type==='saved'?saved.has(c.dataset.id):c.dataset.type===vals.type));c.hidden=!ok;if(ok)n++});if(count)count.textContent=`${n} ${n===1?'gift idea':'gift ideas'}`;if(empty)empty.hidden=n>0}function sync(){document.querySelectorAll('.save').forEach(b=>{let on=saved.has(b.dataset.id);b.setAttribute('aria-pressed',String(on));b.textContent=on?'♥':'♡';b.setAttribute('aria-label',`${on?'Unsave':'Save'} ${b.dataset.name}`)});document.querySelectorAll('[data-saved-count]').forEach(e=>e.textContent=String(saved.size))}document.querySelectorAll('.save').forEach(b=>b.addEventListener('click',()=>{let on=saved.has(b.dataset.id);if(on)saved.delete(b.dataset.id);else saved.add(b.dataset.id);try{localStorage.setItem('pgg-saved',JSON.stringify([...saved]));if(status)status.textContent=on?'Removed from your shortlist.':'Saved to your shortlist on this browser.'}catch{if(status)status.textContent='Saved for this visit. Your browser is blocking persistent storage.'}sync();filter()}));filters.forEach(f=>f.addEventListener('change',filter));document.querySelector('#reset')?.addEventListener('click',()=>{filters.forEach(f=>f.value='');filter()});document.querySelector('[data-show-saved]')?.addEventListener('click',()=>{const t=document.querySelector('[data-filter=type]');if(t){t.value='saved';filter()}});sync();if(filters.length)filter()})();
